------------------------------------- ID: 5680-- Item: agaricus mushroom-- Food Effect: 10 Min, All Races------------------------------------- STR -4-- MND +2--------------------------------------@type TItemFoodlocal itemObject = {}itemObject.onItemCheck = function(target, item, param, caster)    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)enditemObject.onItemUse = function(target, user, item, action)    target:addStatusEffect(xi.effect.FOOD, { duration = 600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })enditemObject.onEffectGain = function(target, effect)    effect:addMod(xi.mod.STR, -4)    effect:addMod(xi.mod.MND, 2)enditemObject.onEffectLose = function(target, effect)endreturn itemObject
